fn cold949_sha(text: &str) -> String {
    joined_digest(text.as_bytes())
}
fn cold949_read(path: &std::path::Path, len: usize, sha: &str) -> Option<String> {
    cold949_reader::read(path, len, sha, COLD949_SOURCE_CAP).ok()
}
fn cold949_check(
    source: &str,
    compiled: &str,
    prior: &str,
    read: &mut impl FnMut(&std::path::Path, usize, &str) -> Option<String>,
) -> Option<()> {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    for (path, text) in [
        (root.join(source), compiled),
        (root.join("e").join(cold949_sha(compiled)), compiled),
        (root.join("e").join(cold949_sha(prior)), prior),
    ] {
        if text.len() > COLD949_SOURCE_CAP {
            return None;
        }
        let actual = read(&path, text.len(), &cold949_sha(text))?;
        if actual != text {
            return None;
        }
    }
    Some(())
}
fn cold949_restore(
    source: &str,
    supplied: &str,
    read: &mut impl FnMut(&std::path::Path, usize, &str) -> Option<String>,
) -> Option<String> {
    let (_, compiled, prior, authoring_sha, edits) = COLD949_ROWS.iter().find(|r| r.0 == source)?;
    if supplied != *compiled {
        return None;
    }
    cold949_check(source, compiled, prior, read)?;
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let authoring_archive = root.join("e").join(authoring_sha);
    let historical_authoring = if cold949_sha(compiled) == *authoring_sha {
        None
    } else {
        use crate::source_reflows_merge::main_e177_final_inputs::declared_history_inputs as history;

        let (part, index) = history::slot(source, authoring_sha)?;
        let row = &history::records(part)[index];
        let length = usize::try_from(row["before_bytes"].as_u64()?).ok()?;
        if length > COLD949_SOURCE_CAP {
            return None;
        }
        let archived = read(&authoring_archive, length, authoring_sha)?;
        let restored = history::expected_value(source, authoring_sha, compiled)?;
        if archived != restored {
            return None;
        }
        Some(restored)
    };
    let authoring = historical_authoring.as_deref().unwrap_or(compiled);
    let mut restored = if source == "src/cleanup_plan/replay/factored/moderate_tests.rs" {
        let marker =
            "\n// Complete immediate predecessor. Literal bodies and tariff expression are\n";
        if authoring.matches(marker).count() != 1 {
            return None;
        }
        authoring.split_once(marker)?.0.to_owned()
    } else {
        authoring.to_owned()
    };
    for &(start, end, before) in edits.iter().rev() {
        if start > end || restored.get(start..end).is_none() {
            return None;
        }
        restored.replace_range(start..end, before);
        if restored.len() > COLD949_SOURCE_CAP {
            return None;
        }
    }
    if restored != *prior {
        return None;
    }
    cold949_check(source, compiled, prior, read)?;
    if historical_authoring.is_some()
        && read(&authoring_archive, authoring.len(), authoring_sha)? != authoring
    {
        return None;
    }
    Some(restored)
}
#[test]
fn cold_builder_threshold_entire_old_caller_selector_tariffs_and_owner_inverses_remain_bound() {
    fn definition<'a>(source: &'a str, marker: &str) -> &'a str {
        let start = source.find(marker).unwrap();
        let end = start + source[start..].find("\n}").unwrap() + 2;
        &source[start..end]
    }
    let current = include_str!("moderate_tests.rs");
    let independent = current
        .split_once("mod before_cold_threshold {\nuse super::*;\n")
        .unwrap()
        .1
        .split_once("\n}\n\n// The test receiver")
        .unwrap()
        .0;
    let old_factored = COLD949_ROWS
        .iter()
        .find(|r| r.0 == "src/cleanup_plan/replay/factored.rs")
        .unwrap()
        .2;
    let old_paired = COLD949_ROWS
        .iter()
        .find(|r| r.0 == "src/cleanup_plan/replay/factored/paired.rs")
        .unwrap()
        .2;
    for (old, marker) in [
        (
            old_factored,
            "pub(super) fn validate_with_index_storage<'hir>(",
        ),
        (old_paired, "pub(super) fn selected_builder_paid("),
        (
            old_paired,
            "pub(super) const BUILDER_SELECTOR_CONTROLS: usize = {",
        ),
        (
            old_paired,
            "const FITTING_REFUSAL_PROBE_CONTROLS: usize = {",
        ),
    ] {
        assert_eq!(definition(independent, marker), definition(old, marker));
    }
    assert_eq!(paired::BUILDER_FACTORED_PATH_THRESHOLD, 128);
    assert!(independent.contains("const BUILDER_FACTORED_PATH_THRESHOLD: usize = 128;"));
    assert_eq!(COLD949_ROWS.len(), 22);
    for &(path, compiled, prior, authoring_sha, _) in COLD949_ROWS {
        assert_eq!(
            cold949_restore(path, compiled, &mut cold949_read).as_deref(),
            Some(prior)
        );
        let half = compiled
            .char_indices()
            .map(|(i, _)| i)
            .take_while(|i| *i <= compiled.len() / 2)
            .last()
            .unwrap_or(0);
        for wrong in [
            String::new(),
            compiled[..half].to_owned(),
            format!("{compiled} "),
            format!("!{}", &compiled[1..]),
        ] {
            assert!(cold949_restore(path, &wrong, &mut |_, _, _| panic!(
                "forged current before acquisition"
            ))
            .is_none());
        }
        if compiled != prior {
            assert!(cold949_restore(path, prior, &mut |_, _, _| panic!(
                "historical source cannot impersonate current"
            ))
            .is_none());
        }
        // Corrupt each actual physical, current archive, original archive,
        // and separately acquired authoring archive, early and late.
        let checks = if cold949_sha(compiled) == authoring_sha {
            6
        } else {
            8
        };
        for corrupt_at in 0..checks {
            for truncate in [true, false] {
                let mut calls = 0;
                let mut injected = |p: &std::path::Path, len, sha: &str| {
                    let mut text = cold949_read(p, len, sha)?;
                    if calls == corrupt_at {
                        if truncate {
                            text.pop();
                        } else {
                            text.push('!');
                        }
                    }
                    calls += 1;
                    Some(text)
                };
                assert!(cold949_restore(path, compiled, &mut injected).is_none());
                assert_eq!(calls, corrupt_at + 1);
            }
        }
    }
    assert!(
        cold949_restore("src/foreign.rs", "foreign", &mut |_, _, _| panic!(
            "unknown source has no read authority"
        ))
        .is_none()
    );
}

// This is an exact historical view for the unchanged trailing-probe consumer,
// never a replacement for its live source/compiled/archive authentication.
pub(in crate::cleanup_plan::replay) fn cold949_previous_input(
    source: &str,
    supplied: &str,
    length: usize,
    sha: &str,
) -> String {
    assert!(supplied.len() <= 2 * 1024 * 1024 && length <= 2 * 1024 * 1024);
    let previous = cold949_restore(source, supplied, &mut cold949_read)
        .expect("actual current helper and complete immediate predecessor");
    assert_eq!(previous.len(), length);
    assert_eq!(cold949_sha(&previous), sha);
    previous
}

// Actual complete new local/argument/receiving carriers, not an IR/result bank.
use crate::cleanup_plan::replay::physical_budget::ByteFailure;
const PAID_UNION_CALL: usize = 2 * std::mem::size_of::<Result<Option<usize>, Diagnostic>>()
    + 2 * std::mem::size_of::<Vec<&[Rc<SkeletonObservation>]>>()
    + 2 * std::mem::size_of::<&mut Automaton>()
    + 2 * std::mem::size_of::<&ResolvedFunction>()
    + 2 * std::mem::size_of::<&mut ReplayBudget>()
    + 2 * std::mem::size_of::<&[Rc<ObservationDag>]>()
    + 2 * std::mem::size_of::<usize>();
const PAID_UNION_ROOT: usize = 4 * std::mem::size_of::<Result<usize, Diagnostic>>()
    + 2 * std::mem::size_of::<Result<(), Diagnostic>>()
    + 2 * std::mem::size_of::<usize>();
const PAID_UNION_ROW: usize = 2 * std::mem::size_of::<&[Rc<SkeletonObservation>]>()
    + 2 * std::mem::size_of::<
        std::iter::Rev<std::slice::Iter<'static, &'static [Rc<SkeletonObservation>]>>,
    >()
    + 2 * std::mem::size_of::<Result<(), Diagnostic>>()
    + 2 * std::mem::size_of::<usize>();
const PAID_UNION_ITEM: usize = 2 * std::mem::size_of::<
    std::slice::Iter<'static, Rc<SkeletonObservation>>,
>() + 2 * std::mem::size_of::<&Rc<SkeletonObservation>>()
    + std::mem::size_of::<Option<usize>>()
    + 2 * std::mem::size_of::<usize>();
const PAID_UNION_SEARCH: usize = 2 * std::mem::size_of::<Result<(), ByteFailure>>()
    + 2 * std::mem::size_of::<std::slice::Iter<'static, (Label, usize)>>()
    + 2 * std::mem::size_of::<(&Label, &usize)>()
    + 2 * std::mem::size_of::<Option<usize>>()
    + 2 * std::mem::size_of::<bool>();
const PAID_UNION_NEW_EDGE: usize = 2 * std::mem::size_of::<Result<usize, Diagnostic>>()
    + 2 * std::mem::size_of::<Result<(), Diagnostic>>()
    + std::mem::size_of::<Label>()
    + std::mem::size_of::<Rc<SkeletonObservation>>()
    + std::mem::size_of::<usize>();
const PAID_UNION_PROBE: usize = 2 * std::mem::size_of::<Result<bool, ByteFailure>>()
    + 2 * std::mem::size_of::<&Rc<ObservationDag>>()
    + 2 * std::mem::size_of::<&mut Vec<&[Rc<SkeletonObservation>]>>()
    + 2 * std::mem::size_of::<&mut ReplayBudget>()
    + 2 * std::mem::size_of::<&ResolvedFunction>()
    + 2 * std::mem::size_of::<usize>()
    + 2 * std::mem::size_of::<std::slice::Iter<'static, Rc<ObservationDag>>>()
    + 2 * std::mem::size_of::<&[Rc<SkeletonObservation>]>()
    + 2 * std::mem::size_of::<bool>();
impl Automaton {
    pub(super) fn paid_flat_union(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        start: usize,
        members: &[Rc<ObservationDag>],
    ) -> Result<Option<usize>, Diagnostic> {
        budget.reserve_bytes(function, PAID_UNION_CALL, "pure union full call controls")?;
        let mut rows = Vec::new();
        for member in members {
            if !Self::paid_union_rows(function, budget, member, 0, &mut rows)
                .map_err(ByteFailure::into_diagnostic)?
            {
                return Ok(None);
            }
        }
        // This fresh region owns every child being mutated; it never extends
        // a child reachable through an earlier DAG memo. Sharing is restricted
        // to exact same live immutable Rc observations, with no cached address.
        budget.reserve_bytes(function, PAID_UNION_ROOT, "pure union root receivers")?;
        let root = self.node(function, budget)?;
        let join = self.node(function, budget)?;
        self.epsilon(function, budget, start, root)?;
        for items in rows.iter().rev() {
            budget.reserve_bytes(function, PAID_UNION_ROW, "pure union row receivers")?;
            let mut at = root;
            for item in *items {
                budget.reserve_bytes(function, PAID_UNION_ITEM, "pure union item receivers")?;
                let mut found = None;
                for (label, target) in self.nodes[at].moves() {
                    budget
                        .reserve_compact_bytes(
                            function,
                            PAID_UNION_SEARCH,
                            "pure union identity search receivers",
                        )
                        .map_err(ByteFailure::into_diagnostic)?;
                    budget
                        .charge_compact(function, 1, "flat observation identity comparison")
                        .map_err(ByteFailure::into_diagnostic)?;
                    if let Label::Observation(existing) = label {
                        if Rc::ptr_eq(existing, item) {
                            found = Some(*target);
                            break;
                        }
                    }
                }
                if let Some(target) = found {
                    at = target;
                } else {
                    budget.reserve_bytes(
                        function,
                        PAID_UNION_NEW_EDGE,
                        "pure union node and movement receivers",
                    )?;
                    let target = self.node(function, budget)?;
                    self.movement(
                        function,
                        budget,
                        at,
                        Label::Observation(item.clone()),
                        target,
                    )?;
                    at = target;
                }
            }
            // Every original member retains its endpoint edge, duplicates too.
            self.epsilon(function, budget, at, join)?;
        }
        Ok(Some(join))
    }
    // Complete pure union only. Empty Seq wrappers are transparent. Nested
    // concatenation/nonempty suffixes keep the original builder. Both limits
    // select storage representation only, never admit or waive replay work.
    fn paid_union_rows<'a>(
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        node: &'a Rc<ObservationDag>,
        depth: usize,
        rows: &mut Vec<&'a [Rc<SkeletonObservation>]>,
    ) -> Result<bool, ByteFailure> {
        budget.reserve_compact_bytes(
            function,
            PAID_UNION_PROBE,
            "pure union shape call receivers",
        )?;
        budget.charge_compact(function, 1, "pure union shape traversal")?;
        if depth >= continuation_storage::FRAME_CAPACITY {
            return Ok(false);
        }
        match &node.kind {
            ObservationDagKind::Seq(None, items) => {
                if rows.len() >= FACTORED_PATH_THRESHOLD {
                    return Ok(false);
                }
                budget.reserve_compact_vec(
                    function,
                    rows,
                    1,
                    "pure union borrowed leaf directory",
                )?;
                rows.push(items);
                Ok(true)
            }
            ObservationDagKind::Seq(Some(prefix), items) if items.is_empty() => {
                Self::paid_union_rows(function, budget, prefix, depth + 1, rows)
            }
            ObservationDagKind::Alt(members) => {
                for member in members {
                    if !Self::paid_union_rows(function, budget, member, depth + 1, rows)? {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
            _ => Ok(false),
        }
    }
